try:
    print('>>> f = getattr')
    print('>>> x = 3')
    print('>>> y = []')
    print('>>> f(x, y)')
    f = getattr
    x = 3
    y = []
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
